const config = $('Worker Config').first().json;
const staticData = $getWorkflowStaticData('global');

if (!staticData.candidateQueue || staticData.candidateQueue.length === 0) {
  return [];
}

// Only process candidates above a priority threshold
// Skip anything that scored below 40 (generic low-gas contract calls)
const MIN_PRIORITY = 40;
const eligible = staticData.candidateQueue.filter(c => (c.priorityScore || 0) >= MIN_PRIORITY);

if (eligible.length === 0) {
  // Queue has items but all are low quality — drain them silently
  staticData.candidateQueue = [];
  return [];
}

// Sort best first and claim top N
eligible.sort((a, b) => (b.priorityScore || 0) - (a.priorityScore || 0));
const batchSize = config.batchSize || 3;
const batch = eligible.slice(0, batchSize);

// Remove claimed items from queue
const claimedHashes = new Set(batch.map(c => c.txHash));
staticData.candidateQueue = staticData.candidateQueue.filter(c => !claimedHashes.has(c.txHash));

return batch.map(tx => ({
  json: {
    ...config,
    ...tx,
    status: 'IN_PROGRESS',
    startedAt: new Date().toISOString()
  }
}));

const item = $input.item.json;
const receipt = $('Fetch Transaction Receipt').item.json.result;
const block   = $('Fetch Block Header').item.json.result;
const debugRes = item.result;
if (!receipt || !block) return [{ json: { ...item, status: 'CAPTURE_FAILED', lastError: 'Missing receipt or block' } }];
let prestate = {};
let prestateMethod = 'eth_fallback';
if (debugRes && !item.error) {
  prestateMethod = 'debug_prestateTracer_diffMode_false';
  for (const [addr, acct] of Object.entries(debugRes)) {
    const storage = {};
    for (const [slot, val] of Object.entries(acct.storage || {})) {
      const k = slot.startsWith('0x') ? slot : '0x' + slot;
      const v = val.startsWith('0x') ? val : '0x' + val;
      if (parseInt(v, 16) !== 0) storage[k] = v;
    }
    prestate[addr.toLowerCase()] = { balance: acct.balance || '0x0', nonce: acct.nonce || '0x0', code: acct.code || '0x', storage };
  }
} else {
  if (item.fromAddress) prestate[item.fromAddress] = { balance: '0x1000000000000000000', nonce: '0x0', code: '0x', storage: {} };
  if (item.toAddress)   prestate[item.toAddress]   = { balance: '0x0', nonce: '0x1', code: '0x', storage: {} };
}
function detectFork(n) {
  if (n >= 22000000) return 'Osaka';
  if (n >= 20000000) return 'Prague';
  if (n >= 19426587) return 'Cancun';
  if (n >= 17034870) return 'Shanghai';
  if (n >= 15537394) return 'Paris';
  return 'Berlin';
}
const fork = detectFork(item.blockNumber);
const fixture = { [`mainnet::${item.txHash}`]: {
  _provenance: { chain: 'mainnet', chainId: '0x1', txHash: item.txHash, blockNumber: block.number, blockNumberDec: item.blockNumber, fork, prestateMethod, candidateType: item.candidateType, harvestedAt: new Date().toISOString() },
  env: { currentCoinbase: block.miner || '0x0000000000000000000000000000000000000000', currentNumber: block.number, currentTimestamp: block.timestamp, currentGasLimit: block.gasLimit, currentBaseFee: block.baseFeePerGas || '0x0', currentDifficulty: '0x0' },
  pre: prestate,
  transaction: { from: item.fromAddress, to: item.toAddress || null, value: item.value || '0x0', data: item.inputData || '0x', gasLimit: '0x' + item.gasLimit.toString(16), gasPrice: block.baseFeePerGas || '0x1' }
}};
const corpusDir = item.corpusDir || 'C:/projects/Schlieren/muscle/corpus';
const safeTxHash = item.txHash.replace(/[^a-zA-Z0-9]/g, '_');
const fixturePath = `${corpusDir}/${safeTxHash}.json`;
return [{ json: { ...item, fixture: JSON.stringify(fixture, null, 2), fixturePath, fork, status: 'FIXTURE_BUILT' } }];
